SELECT (SELECT count(*) FROM "FactoryPlanningBatch") AS planning_batches, (SELECT count(*) FROM "FactoryProductionBatch") AS production_batches, (SELECT count(*) FROM "MrpManufacturingBatch") AS mrp_batches, (SELECT count(*) FROM "InventoryBatch") AS inventory_batches, (SELECT count(*) FROM "FactoryPlanningBooth") AS planning_booths, (SELECT count(*) FROM "FactoryProductionBoothUnit") AS production_units, (SELECT count(*) FROM "MrpBatchUnit") AS mrp_units, (SELECT count(*) FROM "InventoryUnit") AS inventory_units, (SELECT count(*) FROM "BoothUnit") AS booth_units, (SELECT count(*) FROM "Assembly" WHERE "linkedDealId" IS NOT NULL) AS assemblies_linked, (SELECT count(*) FROM "Assembly") AS assemblies, (SELECT count(*) FROM "Deal" WHERE stage = 'WON') AS won_deals, (SELECT count(*) FROM rp_requests) AS rp_requests
